package bench

// ClassifyGo is the hand-written Go equivalent of ClassifyFW.
// It uses the same Tag struct and constants generated by the FW enum transpilation.
func ClassifyGo(tag int) string {
	switch tag {
	case TagLow:
		return "low"
	case TagMedium:
		return "medium"
	case TagHigh:
		return "high"
	default:
		return "unknown"
	}
}
